def snapshot_sqlite_database(name,directory):
    from pathlib import Path
    import sqlite3
    from datetime import datetime,timezone
    directory=Path(directory);directory.mkdir(exist_ok=True)
    target=directory/('workhub-pre-v0110-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')+'.sqlite3')
    source=sqlite3.connect(name,timeout=30)
    dest=sqlite3.connect(str(target))
    try:
        source.backup(dest,pages=256,sleep=.05)
        if dest.execute('PRAGMA integrity_check').fetchone()[0]!='ok':raise RuntimeError('Pre-upgrade database backup verification failed')
    finally:dest.close();source.close()
    return target


def backup_persistent_database(apps,schema_editor):
    # Tests and local/in-memory databases never write a production backup.
    conn=schema_editor.connection
    name=str(conn.settings_dict.get('NAME',''))
    if conn.vendor!='sqlite' or not name.startswith('/var/data/'):return
    target=snapshot_sqlite_database(name,'/var/data/backups')
    print('Workhub v0.11.0 backup: '+str(target)+' integrity=ok',flush=True)


